1192	
1193	  // Walk ops; between each kCommand write and the very next kAbstractcs
1194	  // read by an unrelated caller, there must be at least one kAbstractcs
1195	  // read (the busy poll from write_register_abstract).
1196	  bool saw_cmd = false;
1197	  std::size_t reads_since_cmd = 0;
1198	  bool all_cmds_had_abstractcs_poll = true;
1199	  for (const auto& op : bus.ops) {
1200	    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
1201	      if (saw_cmd && reads_since_cmd == 0)
1202	        all_cmds_had_abstractcs_poll = false;
1203	      saw_cmd = true;
1204	      reads_since_cmd = 0;
1205	    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
1206	               && op.reg == kAbstractcs) {
1207	      ++reads_since_cmd;
1208	    }
1209	  }
1210	  CHECK(all_cmds_had_abstractcs_poll);
