1302	    const auto r = regnos[i];
1303	    if (r >= 0x3B0 && r <= 0x3EF) { ++n_addr; last_addr = i; }
1304	    if (r >= 0x3A0 && r <= 0x3AF) {
1305	      if ((r & 1u) != 0u) ++n_odd_cfg;
1306	      else { ++n_cfg; if (i < first_cfg) first_cfg = i; }
1307	    }
1308	  }
1309	  CHECK(n_addr == 64u);
1310	  CHECK(n_cfg == 8u);
1311	  CHECK(n_odd_cfg == 0u);
1312	  // cfg activates the entries, so every addr write must precede every cfg
1313	  // write (a cfg-locked entry would discard the addr that follows it).
1314	  CHECK(last_addr < first_cfg);
1315	}
