1615	// ---- v5: L2C MMIO config restore ------------------------------------------
1616	// The writable L2C config registers are written back via Program-Buffer word
1617	// stores (`sw x5, 0(x6)`), gated on HYBRID_FLAG_L2C AND the engine actually
1618	// having an L2C (set_l2c). A store to an absent L2C region would fault the
1619	// Program Buffer, so an engine without one must issue nothing.
1620	
1621	static std::size_t count_progbuf_insn(const std::vector<DmiOp>& ops, uint32_t insn)
1622	{
1623	  std::size_t n = 0;
1624	  for (const auto& op : ops)
1625	    if (op.kind == DmiOp::Kind::Write && op.reg == hybrid::kProgbuf0
1626	        && op.value == insn)
1627	      ++n;
1628	  return n;
1629	}
