#pragma once

#include "hybrid/abstract_command.hpp"
#include "hybrid/dmi_poll.hpp"
#include "hybrid/program_buffer.hpp"
#include "hybrid/state_abi.h"

#include <array>
#include <cstdint>
#include <optional>
#include <stdexcept>
#include <string>

namespace hybrid {

struct DmiBus
{
  virtual ~DmiBus() = default;
  virtual void write(uint8_t reg, uint32_t value) = 0;
  virtual auto read(uint8_t reg) -> uint32_t = 0;
};

inline auto read_register_64(DmiBus& bus, uint16_t regno,
                             const char* poll_label) -> uint64_t;

class ResumeDriver
{
public:
  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
  // dmcontrol/dmstatus are run-control registers specific to this driver.
  static constexpr uint8_t kData0      = kDmiData0;
  static constexpr uint8_t kData1      = kDmiData1;
  static constexpr uint8_t kDmcontrol  = 0x10;
  static constexpr uint8_t kDmstatus   = 0x11;
  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
  static constexpr uint8_t kCommand    = kDmiCommand;

  static constexpr uint16_t kCsrDpc      = 0x7B1;
  static constexpr uint16_t kCsrDcsr     = 0x7B0;
  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
  static constexpr uint16_t kCsrFcsr     = 0x003;
  static constexpr uint16_t kCsrMstatus  = 0x300;
  static constexpr uint16_t kCsrMie      = 0x304;
  static constexpr uint16_t kCsrMtvec    = 0x305;
  static constexpr uint16_t kCsrMscratch = 0x340;
  static constexpr uint16_t kCsrMepc     = 0x341;
  static constexpr uint16_t kCsrMcause   = 0x342;
  static constexpr uint16_t kCsrMtval    = 0x343;
  static constexpr uint16_t kCsrMip      = 0x344;
  static constexpr uint16_t kCsrMcycle   = 0xB00;
  static constexpr uint16_t kCsrMinstret = 0xB02;
  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;

  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;

  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;

  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;

  // mstatus extension-state field: FS (bits 14:13).
  // "Initial" (01) is the minimal enable the abstract FPR writes require.
  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;

  static constexpr unsigned kPollIterations = kDmiPollIterations;

  explicit ResumeDriver(DmiBus& bus) : bus_{bus} {}

  void resume(const hybrid_state_v1& state)
  {
    if (state.magic != HYBRID_STATE_MAGIC)
      throw std::runtime_error("ResumeDriver::resume: bad magic");
    if (state.version != HYBRID_STATE_VERSION)
      throw std::runtime_error("ResumeDriver::resume: unsupported version");
    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
    if (state.priv == 2 || state.priv > 3)
      throw std::runtime_error("ResumeDriver::resume: invalid privilege");

    // dmactive must transition 0->1 in its own write before any other
    // DMCONTROL bit is honored (RISC-V Debug Spec).
    bus_.write(kDmcontrol, kDmcontrolDmactive);
    request_halt();
    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");

    // mstatus: enable FS so the following FPR abstract writes are accepted
    // (FS == Off disables the extension and the hart NACKs the writes). The
    // drained state.mstatus may legitimately carry FS at Off (e.g. an OS
    // context-switched the regs away before the trigger fired) -- gating the
    // write on the drained field skips the enable and silently NACKs every
    // subsequent FPR write. Always write mstatus when FP is in scope;
    // force-OR Initial when the drained field is Off. This enable is local
    // to the vsim phase; the state.mstatus written to the handoff file is
    // left unmodified.
    if (state.flags & HYBRID_FLAG_FP) {
      uint64_t enable_mstatus = state.mstatus;
      if ((enable_mstatus & kMstatusFsMask) == 0)
        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
    }

    // FPR restore (requires mstatus.FS enabled above): one abstract register
    // write per f-reg. Abstract-only by design, like every non-V register
    // block -- the Program Buffer is reserved for state the abstract command
    // space cannot reach.
    if (state.flags & HYBRID_FLAG_FP) {
      for (uint16_t i = 0; i < 32; ++i)
        write_64bit_register(regno_fpr(i), state.fpr[i]);
      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
      // fallback scratch x5 is overwritten by the GPR loop below.
      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
    }

    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
    // in the drained privilege; M-mode states skip the write (prv already 3).
    // Before the GPR loop: a PB fallback would clobber scratch x5.
    if (state.priv != 3) {
      // L2 slice: with PMP implemented and no matching entry, every S/U
      // access faults (priv spec v1.10) -- mirror the producer's PMP block
      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
      // RV64. Tolerant writes: entries beyond what the hart implements
      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);

      const uint64_t dcsr =
        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
      write_csr_abstract_or_pb(kCsrDcsr,
                               (dcsr & ~uint64_t{0x3}) | state.priv);
      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
      // silently measure the ROI in the wrong privilege. Verify and abort.
      const uint64_t got =
        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
        & 0x3u;
      if (got != state.priv)
        throw std::runtime_error(
          "ResumeDriver::resume: engine does not implement privilege level "
          + std::to_string(state.priv)
          + " (dcsr.prv pinned to " + std::to_string(got)
          + "); pick an S/U-capable engine");
    }

    // GPRs + DPC (after every CSR write whose PB fallback uses x5 as
    // scratch, so x5 is safe to overwrite): one abstract register write per
    // GPR.
    for (uint16_t i = 1; i < 32; ++i)
      write_64bit_register(regno_gpr(i), state.gpr[i]);
    write_64bit_register(regno_csr(kCsrDpc), state.pc);

    write_csr_tolerant(kCsrMtvec, state.mtvec);

    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
    // register with no hardware side effects, legal to use inside a trap-free
    // ROI. Restore it so a value stashed before the handoff survives into the
    // vsim phase.
    write_csr_tolerant(kCsrMscratch, state.mscratch);

    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
    // interrupt-free ROI envelope these are ordinary read/write registers, so a
    // value stashed before the handoff must survive into the vsim phase (same
    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
    // hardware-driven pending bits, or mtval on a core that hardwires it)
    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
    // S-mode CSRs the M-only default engine does not implement (L3/L4).
    write_csr_tolerant(kCsrMepc,   state.mepc);
    write_csr_tolerant(kCsrMcause, state.mcause);
    write_csr_tolerant(kCsrMtval,  state.mtval);
    write_csr_tolerant(kCsrMie,    state.mie);
    write_csr_tolerant(kCsrMip,    state.mip);

    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
    // caches) but has no cache model, so without this the cycle engine resumes
    // at the ROI with caches at their reset default -- DISABLED -- and the
    // whole measured window runs uncached, inflating it severalfold. Tolerant
    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
    // write as a no-op, and a drained 0 (caches were off) restores the reset
    // state, so this is always safe to issue.
    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);

    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
    // from QEMU1's drain value. Without this, vsim's local counter starts
    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
    // overwrite here as the GPR loop already ran.
    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);

    clear_cmderr_if_set();
    request_resume();
    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
                   "ResumeDriver resume");
  }

private:
  void request_halt()
  {
    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
  }

  void request_resume()
  {
    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
  }

  void write_64bit_register(uint16_t regno, uint64_t value)
  {
    write_register_abstract(bus_, regno, value);
  }

  // Abstract-first CSR write with Program Buffer fallback.
  // Tries an abstract register write; if the DM signals cmderr, clears it,
  // stages the value in scratch_gpr via abstract GPR write, then executes a
  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
  // to x5 (t0) which the GPR restore loop overwrites later.
  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
                                 uint8_t scratch_gpr = 5)
  {
    write_64bit_register(regno_csr(csr), value);
    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
    write_64bit_register(regno_gpr(scratch_gpr), value);
    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
    exec_progbuf(bus_, std::span<const uint32_t>{pb});
  }

  // Write a CSR-addressable register and clear any cmderr the DM raised.
  // Used for CSRs whose abstract-access support may be implementation
  // dependent; a missing CSR mirrors as a no-op rather than blocking the
  // remaining writes.
  void write_csr_tolerant(uint16_t csr, uint64_t value)
  {
    write_64bit_register(regno_csr(csr), value);
    clear_cmderr_if_set();
  }

  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
  // is rejected until the bits are W1C-cleared. We tolerate per-register
  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
  // error before resuming so the hart isn't left in a stuck state.
  // B17: record the last observed non-zero cmderr and a clear count so a
  // partially-broken restore is observable via the public accessors
  // instead of silently swallowed.
  void clear_cmderr_if_set()
  {
    const auto status = bus_.read(kAbstractcs);
    const auto code = (status & kAbstractcsCmderrMask) >> 8;
    if (code != 0u) {
      last_observed_cmderr_ = code;
      ++cmderr_clear_count_;
      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
    }
  }

  DmiBus& bus_;
  uint32_t last_observed_cmderr_ = 0;
  uint64_t cmderr_clear_count_   = 0;

public:
  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
  // at least one abstract write tripped a sticky cmderr the restore
  // tolerated by clearing. cmderr_clear_count() is the total number of
  // such clears across all calls into clear_cmderr_if_set() this run.
  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
};

// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
// via an Abstract Command. Halts-and-reads contract: caller must have the
// hart in the halted state. Shared by StateDrain (drain at exit). If
// abstractcs.cmderr goes sticky after the command, the helper clears it and
// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
// instead of corrupting the adjacent field.
inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
                                     const char* poll_label
                                       = "read_register_64")
  -> std::optional<uint64_t>
{
  using RD = ResumeDriver;
  bus.write(RD::kCommand,
            access_register_command(regno, AarSize::Bits64, /*write=*/false));
  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
  const auto status = bus.read(RD::kAbstractcs);
  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
    return std::nullopt;
  }
  const uint64_t lo = bus.read(RD::kData0);
  const uint64_t hi = bus.read(RD::kData1);
  return lo | (hi << 32);
}

inline auto read_register_64(DmiBus& bus, uint16_t regno,
                             const char* poll_label = "read_register_64")
  -> uint64_t
{
  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
}

}  // namespace hybrid

// ResumeDriver translates a hybrid_state_v1 into a sequence of DMI register
// ops against the RISC-V Debug Module. The orchestration is testable in
// isolation by injecting a recording bus.

#include "hybrid/abstract_command.hpp"
#include "hybrid/program_buffer.hpp"
#include "hybrid/resume_driver.hpp"
#include "hybrid/state_abi.h"

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include <doctest.h>

#include <cstdint>
#include <deque>
#include <optional>
#include <set>
#include <unordered_map>
#include <vector>

namespace {

// DMI register addresses from RISC-V Debug Spec 1.0.
constexpr uint8_t kDmcontrol  = 0x10;
constexpr uint8_t kDmstatus   = 0x11;
constexpr uint8_t kAbstractcs = 0x16;
constexpr uint8_t kCommand    = 0x17;
constexpr uint8_t kData0      = 0x04;
constexpr uint8_t kData1      = 0x05;

// CSR numbers from Debug Spec.
constexpr uint16_t kCsrDpc  = 0x7B1;
constexpr uint16_t kCsrDcsr = 0x7B0;

struct DmiOp
{
  enum class Kind
  {
    Write,
    Read,
  };
  Kind kind;
  uint8_t reg;
  uint32_t value;  // for writes only
};

struct RecordingBus final : hybrid::DmiBus
{
  std::vector<DmiOp> ops;

  // Test-controlled response values for reads.
  uint32_t dmstatus_value = 0;       // bit 9: allhalted, bit 17: allresumeack
  uint32_t abstractcs_value = 0;     // fallback when queue is empty
  std::deque<uint32_t> abstractcs_queue; // queued reads drain first

  // When set, an abstract write-COMMAND to this CSR regno raises a sticky
  // cmderr (cleared by the W1C abstractcs write the driver issues on its PB
  // fallback). Models real hardware and -- unlike positional queueing -- is
  // robust to however many unrelated abstract ops precede the targeted write.
  std::optional<uint16_t> fail_csr_write;

  // One-shot: when true, the NEXT kExecProgbufCmd write raises sticky cmderr
  // (so exec_progbuf throws after its post-exec abstractcs poll). The flag
  // re-arms to false after firing - tests can flip it back on to fail a
  // later PB exec.
  bool fail_next_pb_exec = false;

  // Mini register file: abstract write-COMMANDs latch the staged DATA0/DATA1
  // into regfile[regno]; abstract read-COMMANDs load it back so read-modify-
  // write-verify sequences observe their own writes. Regnos in warl_ignore
  // model WARL fields the hart pins (the write is recorded but discarded),
  // e.g. dcsr.prv on a core without S/U modes.
  std::unordered_map<uint16_t, uint64_t> regfile;
  std::set<uint16_t> warl_ignore;

  void write(uint8_t reg, uint32_t value) override
  {
    ops.push_back({DmiOp::Kind::Write, reg, value});
    if (reg == kData0) staged_data0_ = value;
    if (reg == kData1) staged_data1_ = value;
    if (reg == kAbstractcs && (value & kCmderrMask) != 0u)
      cmderr_sticky_ = false;  // W1C clear
    if (reg == kCommand && fail_csr_write) {
      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
      const bool is_write = ((value >> 16) & 1u) != 0u;
      if (is_write && regno == hybrid::regno_csr(*fail_csr_write))
        cmderr_sticky_ = true;
    }
    if (reg == kCommand && value != hybrid::kExecProgbufCmd) {
      const auto regno    = static_cast<uint16_t>(value & 0xFFFFu);
      const bool is_write = ((value >> 16) & 1u) != 0u;
      if (is_write) {
        if (!warl_ignore.count(regno))
          regfile[regno] = (uint64_t{staged_data1_} << 32) | staged_data0_;
      } else {
        const auto it = regfile.find(regno);
        const uint64_t v = (it == regfile.end()) ? 0u : it->second;
        pending_data0_ = static_cast<uint32_t>(v);
        pending_data1_ = static_cast<uint32_t>(v >> 32);
      }
    }
    if (reg == kCommand && value == hybrid::kExecProgbufCmd
        && fail_next_pb_exec) {
      cmderr_sticky_ = true;
      fail_next_pb_exec = false;
    }
  }

  auto read(uint8_t reg) -> uint32_t override
  {
    ops.push_back({DmiOp::Kind::Read, reg, 0});
    if (reg == kDmstatus) return dmstatus_value;
    if (reg == kData0)   return pending_data0_;
    if (reg == kData1)   return pending_data1_;
    if (reg == kAbstractcs) {
      if (cmderr_sticky_) return kCmderrMask;
      if (!abstractcs_queue.empty()) {
        auto v = abstractcs_queue.front();
        abstractcs_queue.pop_front();
        return v;
      }
      return abstractcs_value;
    }
    return 0;
  }

private:
  static constexpr uint32_t kCmderrMask = 0x7u << 8;
  bool cmderr_sticky_ = false;
  uint32_t staged_data0_  = 0;
  uint32_t staged_data1_  = 0;
  uint32_t pending_data0_ = 0;
  uint32_t pending_data1_ = 0;
};

auto rv64_state(uint64_t pc, uint64_t x10) -> hybrid_state_v1
{
  hybrid_state_v1 s{};
  s.magic = HYBRID_STATE_MAGIC;
  s.version = HYBRID_STATE_VERSION;
  s.flags = HYBRID_FLAG_RV64;
  s.pc = pc;
  s.priv = 3;
  s.gpr[10] = x10;
  return s;
}

auto find_write(const std::vector<DmiOp>& ops, uint8_t reg)
  -> std::vector<uint32_t>
{
  std::vector<uint32_t> values;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == reg)
      values.push_back(op.value);
  return values;
}

auto count_writes_to(const std::vector<DmiOp>& ops, uint8_t reg) -> std::size_t
{
  std::size_t n = 0;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == reg) ++n;
  return n;
}

}  // namespace

TEST_CASE("resume halts the hart before any abstract command")
{
  RecordingBus bus;
  // dmstatus answers halted+resumeack so poll loops finish on the first read.
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(/*pc=*/0x80001000, /*x10=*/0xdeadbeef));

  // The first write must prime dmactive (DM out of reset) BEFORE haltreq is
  // accepted; the second write must add haltreq while keeping dmactive set.
  REQUIRE(bus.ops.size() >= 2);

  const auto& prime = bus.ops[0];
  CHECK(prime.kind == DmiOp::Kind::Write);
  CHECK(prime.reg == kDmcontrol);
  CHECK((prime.value & 1u) == 1u);                  // dmactive
  CHECK(((prime.value >> 31) & 1u) == 0u);          // haltreq NOT yet set

  const auto& halt = bus.ops[1];
  CHECK(halt.kind == DmiOp::Kind::Write);
  CHECK(halt.reg == kDmcontrol);
  CHECK((halt.value & 1u) == 1u);                   // dmactive still set
  CHECK(((halt.value >> 31) & 1u) == 1u);           // haltreq
}

TEST_CASE("resume programs x1..x31 via DATA0/DATA1 + COMMAND, skipping x0")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0xdeadbeef);
  for (int i = 0; i < 32; ++i) s.gpr[i] = 0xa00000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  std::vector<uint32_t> cmds;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
      cmds.push_back(op.value);

  CHECK(cmds.size() >= 31);

  for (int i = 1; i < 32; ++i) {
    const auto expect =
      hybrid::access_register_command(hybrid::regno_gpr(i),
                                      hybrid::AarSize::Bits64, /*write=*/true);
    CHECK(cmds[i - 1] == expect);
  }

  for (const auto& cmd : cmds) {
    const uint16_t regno = cmd & 0xffffu;
    CHECK(regno != hybrid::regno_gpr(0));
  }
}

TEST_CASE("resume writes DPC = state.pc")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  constexpr uint64_t pc = 0x12345678'9ABCDEF0ULL;
  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(pc, 0));

  // Look for the COMMAND write that targets CSR DPC (regno=0x7B1).
  std::vector<std::size_t> dpc_cmd_indices;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xffffu) == kCsrDpc) {
      dpc_cmd_indices.push_back(i);
    }
  }
  REQUIRE(dpc_cmd_indices.size() == 1);

  // Immediately preceding writes must set DATA0=low32(pc), DATA1=high32(pc).
  const auto cmd_idx = dpc_cmd_indices[0];
  REQUIRE(cmd_idx >= 2);
  const auto& d0 = bus.ops[cmd_idx - 2];
  const auto& d1 = bus.ops[cmd_idx - 1];
  CHECK(d0.kind == DmiOp::Kind::Write);
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(pc & 0xffffffffu));
  CHECK(d1.kind == DmiOp::Kind::Write);
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t((pc >> 32) & 0xffffffffu));
}

TEST_CASE("resume issues resumereq after register programming")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  // The last DMCONTROL write must clear haltreq and set resumereq.
  const auto dmctl_writes = find_write(bus.ops, kDmcontrol);
  REQUIRE(dmctl_writes.size() >= 2);
  const auto last = dmctl_writes.back();
  CHECK((last & 1u) == 1u);                  // dmactive still on
  CHECK(((last >> 31) & 1u) == 0u);          // haltreq cleared
  CHECK(((last >> 30) & 1u) == 1u);          // resumereq set
}

TEST_CASE("resume polls DMSTATUS for halted before programming registers")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  // At least one DMSTATUS read happened, and it occurred before the first
  // DATA0/DATA1 write.
  std::optional<std::size_t> first_dmstatus_read;
  std::optional<std::size_t> first_data_write;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Read && op.reg == kDmstatus
        && !first_dmstatus_read)
      first_dmstatus_read = i;
    if (op.kind == DmiOp::Kind::Write && op.reg == kData0 && !first_data_write)
      first_data_write = i;
  }
  REQUIRE(first_dmstatus_read);
  REQUIRE(first_data_write);
  CHECK(*first_dmstatus_read < *first_data_write);
}

TEST_CASE("resume rejects a state with wrong magic")
{
  RecordingBus bus;
  hybrid::ResumeDriver driver(bus);

  hybrid_state_v1 bad{};
  bad.version = HYBRID_STATE_VERSION;
  bad.magic = 0xDEADBEEFu;
  CHECK_THROWS(driver.resume(bad));
}

TEST_CASE("resume issues exactly one COMMAND per programmed register")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  // x1..x31 + DPC at minimum (x0 skipped). We do not yet program FPR/CSR/V.
  CHECK(count_writes_to(bus.ops, kCommand) >= 32u);
}

namespace {

auto cmd_regnos(const std::vector<DmiOp>& ops) -> std::vector<uint16_t>
{
  std::vector<uint16_t> ns;
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand)
      ns.push_back(static_cast<uint16_t>(op.value & 0xffffu));
  return ns;
}

auto contains_regno(const std::vector<uint16_t>& ns, uint16_t regno) -> bool
{
  for (auto n : ns) if (n == regno) return true;
  return false;
}

}  // namespace

TEST_CASE("resume does NOT program M-mode CSRs/PMP via DM Abstract Commands; "
          "those fields are pass-through-merged at drain time instead")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mstatus = 0x1800ULL;
  for (int i = 0; i < HYBRID_PMP_CFG_NUM; ++i)  s.pmpcfg[i]  = 0xa0 + i;
  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb0 + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  // mcycle(0xb00)/minstret(0xb02) are restored by resume (F-T2.4), mscratch
  // (0x340) since L23, and mepc(0x341)/mcause(0x342)/mtval(0x343)/mip(0x344)/
  // mie(0x304) since L24 -- none of those belong in this "must not program"
  // list. It now covers mstatus(0x300, restored only under FP; this state
  // does not carry it) plus the S-mode CSRs medeleg(0x302)/mideleg(0x303)/
  // satp(0x180) that the M-only default engine does not implement; those stay
  // drain-time pass-through.
  for (uint16_t csr : {0x300, 0x302, 0x303, 0x180})
    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(csr)));
  for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; ++i)
    CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x3a0 + i)));
}

TEST_CASE("resume with HYBRID_FLAG_FP programs f0..f31 via Abstract Commands")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;  // mstatus.FS = Dirty: FPRs are writable
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0xf000000000000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 0; i < 32; ++i)
    CHECK(contains_regno(ns, hybrid::regno_fpr(i)));
}

TEST_CASE("resume with HYBRID_FLAG_FP: mstatus written before FPR Abstract Commands")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;
  s.fpr[0]  = 0xdeadbeefcafef00dULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  std::optional<std::size_t> mstatus_cmd_idx;
  std::optional<std::size_t> f0_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (!mstatus_cmd_idx && regno == hybrid::regno_csr(0x300))
      mstatus_cmd_idx = i;
    if (!f0_cmd_idx && regno == hybrid::regno_fpr(0))
      f0_cmd_idx = i;
  }
  REQUIRE(mstatus_cmd_idx.has_value());
  REQUIRE(f0_cmd_idx.has_value());
  CHECK(*mstatus_cmd_idx < *f0_cmd_idx);
}

TEST_CASE("resume with HYBRID_FLAG_FP: FPR writes carry the state value via DATA0/DATA1")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;
  s.fpr[7]  = 0x0123456789ABCDEFULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  std::optional<std::size_t> f7_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_fpr(7)) {
      f7_cmd_idx = i;
      break;
    }
  }
  REQUIRE(f7_cmd_idx.has_value());
  REQUIRE(*f7_cmd_idx >= 2);
  const auto& d0 = bus.ops[*f7_cmd_idx - 2];
  const auto& d1 = bus.ops[*f7_cmd_idx - 1];
  CHECK(d0.kind == DmiOp::Kind::Write);
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(s.fpr[7] & 0xFFFFFFFFu));
  CHECK(d1.kind == DmiOp::Kind::Write);
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t(s.fpr[7] >> 32));
}

TEST_CASE("L20: resume with HYBRID_FLAG_FP restores fcsr via abstract "
          "command, after the mstatus.FS enable")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;
  s.fcsr    = 0x21;  // frm=RTZ(1) << 5 | fflags=NX

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  std::optional<std::size_t> mstatus_cmd_idx, fcsr_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const auto regno = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (!mstatus_cmd_idx && regno == hybrid::regno_csr(0x300))
      mstatus_cmd_idx = i;
    if (!fcsr_cmd_idx && regno == hybrid::regno_csr(0x003))
      fcsr_cmd_idx = i;
  }
  REQUIRE(mstatus_cmd_idx.has_value());
  REQUIRE(fcsr_cmd_idx.has_value());
  CHECK(*mstatus_cmd_idx < *fcsr_cmd_idx);

  // The fcsr value rides DATA0/DATA1 of that abstract write.
  REQUIRE(*fcsr_cmd_idx >= 2);
  const auto& d0 = bus.ops[*fcsr_cmd_idx - 2];
  const auto& d1 = bus.ops[*fcsr_cmd_idx - 1];
  CHECK(d0.kind == DmiOp::Kind::Write);
  CHECK(d0.reg == kData0);
  CHECK(d0.value == 0x21u);
  CHECK(d1.kind == DmiOp::Kind::Write);
  CHECK(d1.reg == kData1);
  CHECK(d1.value == 0u);
}

TEST_CASE("L20: resume without HYBRID_FLAG_FP issues no fcsr write")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.fcsr = 0x21;  // present in the file but FP not flagged live

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  CHECK_FALSE(contains_regno(cmd_regnos(bus.ops), hybrid::regno_csr(0x003)));
}

TEST_CASE("L23: resume restores mscratch (software scratch CSR) via an "
          "abstract command, carrying the drained value on DATA0/DATA1")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mscratch = 0xCAFEBABEDEADBEEFULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Find the write-COMMAND targeting mscratch (0x340); its value rides the
  // DATA0/DATA1 written immediately before (same shape as the fcsr restore).
  std::optional<std::size_t> ms_cmd_idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x340)
        && ((op.value >> 16) & 1u)) {
      ms_cmd_idx = i;
      break;
    }
  }
  REQUIRE(ms_cmd_idx.has_value());
  REQUIRE(*ms_cmd_idx >= 2);
  const auto& d0 = bus.ops[*ms_cmd_idx - 2];
  const auto& d1 = bus.ops[*ms_cmd_idx - 1];
  CHECK(d0.kind == DmiOp::Kind::Write);
  CHECK(d0.reg == kData0);
  CHECK(d0.value == uint32_t(s.mscratch & 0xFFFFFFFFu));
  CHECK(d1.kind == DmiOp::Kind::Write);
  CHECK(d1.reg == kData1);
  CHECK(d1.value == uint32_t(s.mscratch >> 32));
}

TEST_CASE("L24: resume restores mepc/mcause/mtval/mip/mie via abstract "
          "commands, each carrying its drained value on DATA0/DATA1")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mepc   = 0x1111111122222222ULL;
  s.mcause = 0x8000000000000007ULL;  // machine timer interrupt cause encoding
  s.mtval  = 0x3333333344444444ULL;
  s.mip    = 0x0000000000000080ULL;  // MTIP
  s.mie    = 0x0000000000000888ULL;  // MTIE | MEIE | MSIE

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Each CSR gets a write-COMMAND (bit 16 set) carrying its value on the
  // DATA0/DATA1 written immediately before (same shape as fcsr/mscratch).
  const std::pair<uint16_t, uint64_t> want[] = {
    {0x341, s.mepc}, {0x342, s.mcause}, {0x343, s.mtval},
    {0x344, s.mip},  {0x304, s.mie},
  };
  for (const auto& [csr, val] : want) {
    std::optional<std::size_t> cmd_idx;
    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
      const auto& op = bus.ops[i];
      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
          && (op.value & 0xFFFFu) == hybrid::regno_csr(csr)
          && ((op.value >> 16) & 1u)) {
        cmd_idx = i;
        break;
      }
    }
    REQUIRE(cmd_idx.has_value());
    REQUIRE(*cmd_idx >= 2);
    const auto& d0 = bus.ops[*cmd_idx - 2];
    const auto& d1 = bus.ops[*cmd_idx - 1];
    CHECK(d0.reg == kData0);
    CHECK(d0.value == uint32_t(val & 0xFFFFFFFFu));
    CHECK(d1.reg == kData1);
    CHECK(d1.value == uint32_t(val >> 32));
  }
}

TEST_CASE("Andes cache fix: resume restores mcache_ctl + mmisc_ctl via "
          "abstract commands, each carrying its drained value on DATA0/DATA1")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.mcache_ctl = 0x703ULL;  // crt0's I-cache + D-cache + prefetch enable
  s.mmisc_ctl  = 0x40ULL;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Each Andes setup CSR gets a write-COMMAND (bit 16 set) carrying its value
  // on the DATA0/DATA1 written immediately before (same shape as fcsr/mscratch).
  const std::pair<uint16_t, uint64_t> want[] = {
    {0x7CA, s.mcache_ctl}, {0x7D0, s.mmisc_ctl},
  };
  for (const auto& [csr, val] : want) {
    std::optional<std::size_t> cmd_idx;
    for (std::size_t i = 0; i < bus.ops.size(); ++i) {
      const auto& op = bus.ops[i];
      if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
          && (op.value & 0xFFFFu) == hybrid::regno_csr(csr)
          && ((op.value >> 16) & 1u)) {
        cmd_idx = i;
        break;
      }
    }
    REQUIRE(cmd_idx.has_value());
    REQUIRE(*cmd_idx >= 2);
    const auto& d0 = bus.ops[*cmd_idx - 2];
    const auto& d1 = bus.ops[*cmd_idx - 1];
    CHECK(d0.reg == kData0);
    CHECK(d0.value == uint32_t(val & 0xFFFFFFFFu));
    CHECK(d1.reg == kData1);
    CHECK(d1.value == uint32_t(val >> 32));
  }
}

TEST_CASE("resume without HYBRID_FLAG_FP: no FPR Abstract Commands issued")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  for (int i = 0; i < 32; ++i) s.fpr[i] = 0xf000000000000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 0; i < 32; ++i)
    CHECK_FALSE(contains_regno(ns, hybrid::regno_fpr(i)));
}

TEST_CASE("resume restores GPRs and FPRs via abstract writes only -- no PB "
          "load-sweep")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);  // halted + resumeack
  bus.abstractcs_value = 8u << 24;              // progbufsize = 8 (this DM)

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0x6000ULL;  // FS = Dirty: FPRs writable
  for (uint16_t i = 1; i < 32; ++i) s.gpr[i] = 0xB0000000ULL + i;
  for (int i = 0; i < 32; ++i)      s.fpr[i] = 0xF0000000ULL + i;

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Every GPR and FPR arrives via its own abstract register write...
  const auto ns = cmd_regnos(bus.ops);
  for (uint16_t i = 1; i < 32; ++i)
    CHECK(contains_regno(ns, hybrid::regno_gpr(i)));
  for (uint16_t i = 0; i < 32; ++i)
    CHECK(contains_regno(ns, hybrid::regno_fpr(i)));

  // ...and no Program Buffer execution happens at all (a memory-load sweep
  // through the PB would be the batched alternative; the only legitimate PB
  // use in this state is none at all).
  for (const auto& op : bus.ops)
    CHECK_FALSE((op.kind == DmiOp::Kind::Write && op.reg == kCommand
                 && op.value == hybrid::kExecProgbufCmd));
}

TEST_CASE("B4: resume with HYBRID_FLAG_FP and drained FS=Off still writes "
          "mstatus with FS != Off so FPR abstract writes are accepted")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags  |= HYBRID_FLAG_FP;
  s.mstatus = 0;                  // FS = 00 (Off)

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Find the abstract write that targets mstatus (regno = 0x300) and verify
  // FS (bits 14:13) was forced non-zero. The drained mstatus has FS=Off but
  // the hart needs FS != Off to accept abstract FPR writes; the gate must
  // OR in FS=Initial without altering the wire-format state.mstatus.
  std::optional<uint32_t> mstatus_low32;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x300)
        && ((op.value >> 16) & 1u)) {
      REQUIRE(i >= 2);
      mstatus_low32 = bus.ops[i - 2].value;
      break;
    }
  }
  REQUIRE(mstatus_low32.has_value());
  CHECK((*mstatus_low32 & 0x6000u) != 0u);
}

TEST_CASE("B17: cleared cmderr surfaces via diagnostic side-channel")
{
  // The restore tail's clear_cmderr_if_set() swallows any sticky cmderr
  // from earlier per-register failures so the resume can proceed. Without
  // a side channel, a partially-broken restore is invisible. Pin the
  // contract: when a CSR write fails (sticky cmderr -> PB fallback path
  // also clears it... but with no PB fallback for tolerant CSRs, the
  // tail-clear is the surviving signal), the driver records the last
  // observed non-zero cmderr in last_observed_cmderr() / records a
  // non-zero clear count.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  // Force the mtvec abstract write to fail. mtvec goes through
  // write_csr_tolerant which intentionally does NOT take the PB
  // fallback; it just clears cmderr at the end. So the failure
  // is only visible via the side channel.
  bus.fail_csr_write = 0x305;  // CSR mtvec

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0));

  CHECK(driver.cmderr_clear_count() > 0u);
  CHECK(driver.last_observed_cmderr() != 0u);
}

TEST_CASE("B9: write_csr_abstract_or_pb busy-poll precedes cmderr inspection")
{
  // The B9 audit claimed write_csr_abstract_or_pb reads abstractcs without
  // first polling busy. In fact write_64bit_register -> write_register_abstract
  // calls poll_until_clear(busy) before returning, so by the time the cmderr
  // check runs, busy is already clear. This test pins that contract: between
  // every kCommand write and the next kAbstractcs read, the recorded ops
  // must include at least one kAbstractcs read (the busy poll). If a future
  // refactor regresses by removing the chained poll, this test fails.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  hybrid::ResumeDriver driver(bus);
  driver.resume(rv64_state(0x80001000, 0xdeadbeef));

  // Walk ops; between each kCommand write and the very next kAbstractcs
  // read by an unrelated caller, there must be at least one kAbstractcs
  // read (the busy poll from write_register_abstract).
  bool saw_cmd = false;
  std::size_t reads_since_cmd = 0;
  bool all_cmds_had_abstractcs_poll = true;
  for (const auto& op : bus.ops) {
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand) {
      if (saw_cmd && reads_since_cmd == 0)
        all_cmds_had_abstractcs_poll = false;
      saw_cmd = true;
      reads_since_cmd = 0;
    } else if (saw_cmd && op.kind == DmiOp::Kind::Read
               && op.reg == kAbstractcs) {
      ++reads_since_cmd;
    }
  }
  CHECK(all_cmds_had_abstractcs_poll);
  // The final kCommand write must also be followed by an abstractcs read.
  CHECK(reads_since_cmd > 0u);
}

TEST_CASE("L6: S-mode resume writes dcsr.prv = state.priv before resumereq")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.priv = 1;  // S-mode at the drain boundary

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  // Exactly one write-COMMAND must target dcsr (0x7B0). The driver
  // read-modify-writes dcsr; the recording bus answers 0 for the read, so
  // the DATA0 staged two ops earlier is exactly the prv field.
  std::vector<std::size_t> idx;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xffffu) == kCsrDcsr
        && ((op.value >> 16) & 1u) != 0u) {
      idx.push_back(i);
    }
  }
  REQUIRE(idx.size() == 1);
  REQUIRE(idx[0] >= 2);
  const auto& d0 = bus.ops[idx[0] - 2];
  CHECK(d0.kind == DmiOp::Kind::Write);
  CHECK(d0.reg == kData0);
  CHECK((d0.value & 0x3u) == 1u);

  // The dcsr write must land before resumereq (bit 30 of dmcontrol).
  std::size_t resume_idx = bus.ops.size();
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kDmcontrol
        && ((op.value >> 30) & 1u) != 0u) {
      resume_idx = i;
      break;
    }
  }
  CHECK(idx[0] < resume_idx);
}

TEST_CASE("L6: resume rejects reserved or out-of-range privilege values")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  hybrid::ResumeDriver driver(bus);

  auto s = rv64_state(0x80001000, 0);
  s.priv = 2;  // reserved encoding (H-mode slot)
  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);

  s.priv = 4;  // out of the 2-bit prv field entirely
  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);

  // No abstract command may have been issued for a rejected state.
  CHECK(count_writes_to(bus.ops, kCommand) == 0u);
}

TEST_CASE("L6/L2: S/U resume mirrors the producer's PMP block, addr before cfg")
{
  // With PMP implemented and no matching entry, every S/U access faults
  // (priv spec v1.10) -- an S/U ROI cannot even fetch its first insn on the
  // vsim side unless the producer's PMP block is mirrored in.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.priv = 0;  // U-mode
  for (int i = 0; i < HYBRID_PMP_ADDR_NUM; ++i) s.pmpaddr[i] = 0xb000 + i;
  s.pmpcfg[0] = 0x1f;  // entry 0: NAPOT, RWX

  hybrid::ResumeDriver driver(bus);
  driver.resume(s);

  std::vector<uint16_t> regnos;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && ((op.value >> 16) & 1u) != 0u)
      regnos.push_back(static_cast<uint16_t>(op.value & 0xffffu));

  // All 64 pmpaddr CSRs (0x3B0..0x3EF) and the 8 even pmpcfg CSRs
  // (0x3A0,0x3A2,..,0x3AE -- odd ones do not exist on RV64) are written.
  std::size_t first_cfg = regnos.size(), last_addr = 0;
  std::size_t n_addr = 0, n_cfg = 0, n_odd_cfg = 0;
  for (std::size_t i = 0; i < regnos.size(); ++i) {
    const auto r = regnos[i];
    if (r >= 0x3B0 && r <= 0x3EF) { ++n_addr; last_addr = i; }
    if (r >= 0x3A0 && r <= 0x3AF) {
      if ((r & 1u) != 0u) ++n_odd_cfg;
      else { ++n_cfg; if (i < first_cfg) first_cfg = i; }
    }
  }
  CHECK(n_addr == 64u);
  CHECK(n_cfg == 8u);
  CHECK(n_odd_cfg == 0u);
  // cfg activates the entries, so every addr write must precede every cfg
  // write (a cfg-locked entry would discard the addr that follows it).
  CHECK(last_addr < first_cfg);
}

TEST_CASE("L6: resume aborts loudly when the hart pins dcsr.prv (no S/U)")
{
  // An M-only core (e.g. NDS_NUM_PRIVILEGE_LEVELS=1 RTL) WARL-pins
  // dcsr.prv to 3. Silently resuming would measure the ROI in the wrong
  // privilege; the driver must verify its write took and throw instead.
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);
  bus.regfile[hybrid::regno_csr(kCsrDcsr)] = 0x40000003ULL;  // reset: prv=M
  bus.warl_ignore.insert(hybrid::regno_csr(kCsrDcsr));

  auto s = rv64_state(0x80001000, 0);
  s.priv = 1;

  hybrid::ResumeDriver driver(bus);
  CHECK_THROWS_AS(driver.resume(s), std::runtime_error);
}

